const analysisRaw = $('Claude: Analyze Content').first().json;
const toneRaw = $('Claude: Extract Tone').first().json;
const vars = $('Set Variables').first().json;

// Extraer texto de la respuesta de Claude
const analysisText = analysisRaw.content?.[0]?.text || '{}';
const toneText = toneRaw.content?.[0]?.text || '{}';

// Parsear JSON (Claude a veces envuelve en markdown)
const extractJson = (text) => {
  const match = text.match(/```json\n?([\s\S]*?)```/) || text.match(/({[\s\S]*})/);
  try { return JSON.parse(match ? match[1] || match[0] : text); }
  catch { return {}; }
};

const analysis = extractJson(analysisText);
const tone = extractJson(toneText);

return [{
  json: {
    client_id: vars.client_id,
    content_analysis: analysis,
    tone_analysis: tone,
    form_data: vars
  }
}];

// Crear pilares desde el análisis + el form
const data = $('Parse AI Analysis').first().json;
const pillarsRaw = data.form_data.content_pillars_raw || '';
const emergingPillars = data.content_analysis.emerging_pillars || [];

// Parsear pilares del form ("Pilar 1: nombre (descripción)")
const formPillars = pillarsRaw.split('\n')
  .filter(l => l.trim() && l.match(/pilar|1\.|2\.|3\./i))
  .slice(0, 5)
  .map((line, i) => {
    const match = line.match(/:\s*"?([^"]+)"?\s*(?:\((.+)\))?/);
    return {
      client_id: data.client_id,
      name: match?.[1]?.trim() || `Pilar ${i + 1}`,
      description: match?.[2]?.trim() || emergingPillars[i]?.description || '',
      weight: [0.30, 0.30, 0.20, 0.15, 0.05][i] || 0.20,
      sub_topics: emergingPillars[i]?.sample_posts?.slice(0, 3) || [],
      example_hooks: data.content_analysis.top_hooks?.slice(0, 3).map(h => h.hook) || [],
      cta_patterns: data.form_data.cta_types?.split(',').map(c => c.trim()) || []
    };
  });

// Si no hay pilares del form, usar los emergentes del análisis
const pillars = formPillars.length > 0 ? formPillars : emergingPillars.slice(0, 5).map((p, i) => ({
  client_id: data.client_id,
  name: p.name,
  description: p.description,
  weight: [0.30, 0.25, 0.25, 0.20][i] || 0.20,
  sub_topics: p.sample_posts?.slice(0, 3) || [],
  example_hooks: [],
  cta_patterns: []
}));

return pillars.map(p => ({ json: p }));

