const briefRaw = $input.first().json;
const briefText = briefRaw.content?.[0]?.text || 'Error generando brief';
const vars = $('Set Variables').first().json;

return [{
  json: {
    brief_text: briefText,
    client_id: vars.client_id,
    client_slug: vars.client_slug,
    brand_name: vars.brand_name
  }
}];

const body = $input.first().json.body || $input.first().json;
const url = body.url || '';

// Detectar plataforma desde la URL
const platform = 
  url.includes('instagram.com') ? 'instagram' :
  url.includes('tiktok.com') ? 'tiktok' :
  url.includes('linkedin.com') ? 'linkedin' :
  url.includes('youtube.com') || url.includes('youtu.be') ? 'youtube' :
  'blog';

return [{ json: {
  client_id: body.client_id,
  url: url,
  platform: platform,
  pillar_id: body.pillar_id || null,
  source_type: body.source_type || 'inspiration',
  why_it_works: body.why_it_works || null
}}];

