// Determinar qué API usar para buscar métricas según la plataforma
const post = $input.first().json;
const platform = post.platform;
const url = post.content?.match(/https?:\/\/\S+/)?.[0] || '';

// Por ahora devolvemos datos mock de métricas
// En producción: conectar a IG Basic Display API, LinkedIn API, TikTok API
const mockMetrics = {
  views: Math.floor(Math.random() * 5000) + 500,
  likes: Math.floor(Math.random() * 500) + 50,
  comments: Math.floor(Math.random() * 50) + 5,
  engagement_rate: (Math.random() * 0.08 + 0.02).toFixed(3),
  shares: Math.floor(Math.random() * 30),
  saves: platform === 'instagram' ? Math.floor(Math.random() * 100) : 0
};

const engagement = parseFloat(mockMetrics.engagement_rate);
const isHighPerformer = engagement > 0.05 || mockMetrics.views > 3000;

return [{ json: {
  ...post,
  metrics: mockMetrics,
  is_high_performer: isHighPerformer,
  performance_label: isHighPerformer ? 'viral' : engagement > 0.03 ? 'good' : 'low'
}}];

