// Compilar el Brand Brain context para el prompt
const client = $('One Client at a Time').first().json;
const profile = $('Get Brand Profile').first().json;
const pillar = $('Get Active Pillar').first().json;
const recentPosts = $('Get Recent Posts').all().map(i => i.json);

const tov = typeof profile.tone_of_voice === 'string' 
  ? JSON.parse(profile.tone_of_voice) : (profile.tone_of_voice || {});

const brandContext = `
## MARCA: ${profile.brand_name}

### Misión
${profile.mission || ''}

### Tono de voz
Formalidad: ${tov.formality || 'medium'}
Humor: ${tov.humor || 'low'}
Energía: ${tov.energy || 'high'}
Frases SÍ suenan a la marca: ${JSON.stringify(tov.examples || [])}
Frases NO usar: ${JSON.stringify(tov.anti_examples || [])}

### Personalidad
${JSON.stringify(profile.brand_personality || [])}

### Temas prohibidos
${JSON.stringify(profile.banned_topics || [])}
Frases prohibidas: ${JSON.stringify(profile.banned_phrases || [])}

### Pilar activo esta semana
Nombre: ${pillar.name}
Descripción: ${pillar.description}
Hooks de ejemplo: ${JSON.stringify(pillar.example_hooks || [])}
CTAs: ${JSON.stringify(pillar.cta_patterns || [])}

### Últimos 10 posts (NO repetir estas estructuras)
${recentPosts.map((p, i) => `${i+1}. [${p.platform}] ${(p.content || '').slice(0, 150)}`).join('\n')}
`;

return [{
  json: {
    client_id: client.id,
    client_slug: client.slug,
    brand_name: profile.brand_name,
    pillar_name: pillar.name,
    pillar_id: pillar.id,
    brand_context: brandContext,
    active_services: client.active_services || []
  }
}];

const response = $input.first().json;
const ctx = $('Build Brand Brain Context').first().json;
const rawText = response.content?.[0]?.text || '{}';

const extractJson = (text) => {
  const match = text.match(/```json\n?([\s\S]*?)```/) || text.match(/({[\s\S]*})/);
  try { return JSON.parse(match ? match[1] || match[0] : text); }
  catch { return { posts: [] }; }
};

const parsed = extractJson(rawText);
const posts = parsed.posts || [];

// Calcular tokens y costo para el logger
const tokensIn = response.usage?.input_tokens || 0;
const tokensOut = response.usage?.output_tokens || 0;
const costUsd = tokensIn * 0.000003 + tokensOut * 0.000015;

// Loguear uso de IA
$workflow.emit('GLOBAL_OPS_logger', {
  client_id: ctx.client_id,
  agent: 'content-strategist',
  action: 'generate_posts',
  model: 'claude-sonnet-4-6',
  tokens_in: tokensIn,
  tokens_out: tokensOut,
  cost_usd: costUsd,
  workflow: 'GLOBAL_CONTENT_post-generator',
  success: posts.length > 0
});

return posts.map(post => ({ json: {
  ...post,
  client_id: ctx.client_id,
  client_slug: ctx.client_slug,
  pillar_id: ctx.pillar_id,
  platform: 'instagram',
  status: 'draft'
}}));

// Agrupar posts por cliente para enviar un solo mensaje por cliente
const posts = $input.all().map(i => i.json);
if (!posts.length) return [];

const clientSlug = posts[0].client_slug;
const postList = posts.map((p, i) => 
  `*Post ${i+1}* (${p.format})\n${p.caption.slice(0, 300)}...\n_Visual_: ${p.visual_brief}`
).join('\n\n---\n\n');

return [{
  json: {
    client_slug: clientSlug,
    message: `📝 *Contenido listo para ${clientSlug}*\n\n${postList}\n\n✅ /aprobar [1,2,3]\n❌ /rechazar [número]\n✏️ /editar [número] [nuevo texto]`
  }
}];

